const navIcon=id=>`<svg class="nav-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${navPaths[id]||navPaths.cases}"/></svg>`;
const sectionMembers={workloads:['workloads','workload'],cases:['cases','case','artifact-summary','artifact-logs','artifact-files','artifact-core','artifact-packets','artifact-syscalls','artifact-profile','profile-compare','raw-access','analysis-job'],captures:['captures','capture-goal','capture-compose','capture-processes','capture-network','capture-review','capture-progress','history','recordings','recording-save','live-sources','live-watch'],policies:['policies','policy','policy-editor','policy-review'],profiles:['profiles','profile','profile-editor'],approvals:['approvals','approval'],shares:['shares','share-compose','share-detail'],shared:['shared','shared-case'],admin:['admin','clusters','cluster','enroll','capabilities','permissions','permission-preview','retention','retention-preview','deletion','deletion-detail','capacity','integrations','audit','install','upgrade','privacy-request']};
const sectionFor=id=>Object.keys(sectionMembers).find(k=>sectionMembers[k].includes(id))||id;
const subtitles={'artifact-download':'Save a native file to inspect with your own tools.',overview:'Investigations, recordings, and the next thing that needs you.',workloads:'Choose an application to investigate.',workload:'Observe the whole workload. Collect only what you need.',cases:'Evidence from your ongoing investigations.',captures:'Follow requests and open the evidence already available.',recordings:'Save a window from a recorder that is already running.','live-sources':'Choose an existing recording to watch.','live-watch':'checkout-api · eu-production / payments · pod 8k2p','capture-goal':'Choose the workload and what you want to understand.','capture-compose':'Start with a profile. Add only the evidence you need.','capture-review':'Check the scope, impact, and who can see the results.','capture-processes':'Use a stable rule that survives process restarts.','capture-network':'Choose traffic, representation, and bounded storage.','recording-save':'Preserve a recent window. The recording continues.',history:'Reuse a previous request with current checks.',policies:'Watch for symptoms and collect bounded evidence.',profiles:'Reusable building blocks for common investigations.',admin:'Installation health, access, and data controls.',agent:'Investigate with your preferred MCP client.',approvals:'Review the requests that need a human decision.',shares:'Manage access to selected evidence.',shared:'Evidence others have shared with you.'};
const headingAction=id=>({overview:link('capture-goal','Collect evidence','button primary'),workload:link('capture-goal','Collect evidence','button primary')})[id]||'';
function sectionTabs(id){return ['captures','recordings','live-sources','history'].includes(id)?`<nav class="tabs section-nav" aria-label="Capture views">${[['captures','Requests'],['recordings','Recordings'],['live-sources','Watch live'],['history','History']].map(([key,label])=>`<a href="#/${key}" ${key===id?'aria-current="page"':''}>${label}</a>`).join('')}</nav>`:'';}
const current=()=>location.hash.startsWith('#/')?location.hash.slice(2):'overview';
function stateBody(s,allowed){const state=allowed?demo.state:'denied';if(state==='loading'&&s.id==='artifact-download')return downloadPreparing();if(state==='loading')return `<section class="empty" aria-busy="true"><h2>Loading your authorized view…</h2><p>Evidence and permissions are being checked. Nothing has been submitted.</p></section>`;if(state==='empty')return card('Nothing here yet','<p>No matching items are visible with your current access and filters. Clear filters or return to your workspace.</p>'+link(demo.persona==='recipient'?'shared':'overview','Return to workspace','button'));if(state==='denied')return card('This view is unavailable','<p>Your current access does not allow this operation, or the resource is unavailable. No hidden evidence details are shown.</p>'+link('access','Check your access','button'));if(state==='expired')return card('This view has expired','<p>The preview, evidence or access window is no longer valid. Existing retention deadlines are not extended.</p>'+link(demo.persona==='recipient'?'shared':'history','Return to available items','button'));return (s.id==='artifact-download'&&['offline','quota'].includes(state)?banner('Download is temporarily unavailable',state==='offline'?'The authenticated transfer path cannot currently reach its dependencies. Existing evidence remains retained.':'Transfer capacity is exhausted. Existing evidence and protected incident uploads remain reserved.','warn'):state==='offline'?banner('Cluster connection lost','Stored evidence remains available when authorized. New collection cannot be dispatched; old local work is bounded by its remaining permits.','warn'):state==='quota'?banner('Collection capacity is unavailable','Workload capacity is reserved or exhausted. Other workloads keep their protected allocations. Read existing evidence or retry after the reported cooldown.','warn'):'')+body(s.id);}
function render(focus=true){
 if(current()!=='live-watch'||demo.state!=='normal'||!['maintainer','admin'].includes(demo.persona)){
  if(['Active','Paused'].includes(live.state))live.state=demo.state==='offline'?'Disconnected':demo.state==='expired'?'Expired':demo.state==='denied'?'Access lost':'Closed';
  live.rows=[];live.lastReceived=null;live.selected=null;
 }
 const id=current(),s=screens.find(x=>x.id===id)||screens[0],allowed=s.personas.includes(demo.persona)&&demo.state!=='denied',section=sectionFor(id);
 $('#persona').value=demo.persona;$('#state-picker').value=demo.state;
 $('#screen-picker').innerHTML=screens.filter(x=>x.personas.includes(demo.persona)).map(x=>`<option value="${x.id}" ${x.id===id?'selected':''}>${x.surface_id} · ${x.title}</option>`).join('');
 $('#navigation').innerHTML=navGroups.map(([g,ids])=>{
  const ns=ids.map(i=>screens.find(x=>x.id===i)).filter(x=>x.personas.includes(demo.persona));
  return ns.length?`<div class="nav-label">${g}</div>${ns.map(x=>`<a href="${x.route}" ${x.id===id?'aria-current="page"':x.id===section&&allowed?'data-section="current"':''}>${navIcon(x.id)}${navNames[x.id]||x.title}</a>`).join('')}`:'';
 }).join('');
 const title=allowed?s.title:'Unavailable';
 $('#breadcrumb').innerHTML=allowed?(section!==id&&navNames[section]?`${link(section,navNames[section])}<span aria-hidden="true">/</span>${esc(title)}`:esc(navNames[id]||title)):'Unavailable';
 document.title=`${title} · Asservat prototype`;
 $('#identity-button').textContent=demo.persona==='approver'?'MC':demo.persona==='recipient'?'JL':'AM';
 $('#main').dataset.screen=id;
 $('#main').innerHTML=`<div class="page-heading"><div><h1>${esc(title)}</h1><p>${allowed?esc(subtitles[id]||s.purpose):'Review your effective access.'}</p></div>${allowed&&demo.state==='normal'?headingAction(id):''}</div>${allowed?sectionTabs(id):''}<div class="stack">${stateBody(s,allowed)}</div>`;
 if(allowed&&s.id.startsWith('artifact-')&&s.id!=='artifact-summary'&&s.id!=='artifact-download'&&['normal','offline','quota'].includes(demo.state))$('#main .stack').insertAdjacentHTML('beforeend',expiry(s.id==='artifact-core'));
 if(['offline','quota','loading'].includes(demo.state))document.querySelectorAll('[data-action="capture"],[data-action="save"],[data-action="save-packet"],[data-action="save-syscall"],[data-action="discovery"],[data-action="survey"],[data-action="download-file"]').forEach(x=>{x.disabled=true;x.title='Unavailable in this state';});
 if(current()==='capture-review'&&!demo.profiles.size){const b=document.querySelector('[data-action="capture"]');if(b){b.disabled=true;b.title='Choose at least one evidence profile';}}
 if(s.id==='live-watch'&&allowed)updateLive();
 document.querySelectorAll('.table-wrap').forEach((el,i)=>{el.tabIndex=0;el.setAttribute('role','region');el.setAttribute('aria-label',`${title}: scrollable table ${i+1}`);});
 if(focus&&!$('#prototype-dialog').open)$('#main').focus();
 $('#sidebar').classList.remove('open');$('#menu-toggle').setAttribute('aria-expanded','false');
}
const actions={
capture:['Collect this evidence?','Submit a fresh bounded plan. Intrusive actions remain blocked until an independent grant is valid.','Collect','capture-progress'],
save:['Save existing recordings now?','Snapshot the selected existing packet/syscall sources, ending at first acceptance. This will not trigger other policy actions.','Save recordings','capture-progress'],
cancel:['Cancel remaining work?','Already retained evidence remains governed by its deadline. Ambiguous starts stay accounted. Existing recorders continue.','Cancel remaining work','capture-progress'],
suspend:['Suspend this policy?','Stop admitting new occurrences and source renewals. Existing evidence keeps its deadline.','Suspend','policy'],
'publish-policy':['Submit policy change?','Use authenticated Kubernetes submission or the exact GitOps change. A changed execution scope requires fresh acceptance and applicable review.','Submit change','policy'],
'publish-profile':['Publish this version?','Validate and publish an immutable CaptureProfile version. Existing consumers keep their pinned versions.','Publish','profile'],
share:['Share selected evidence?','Create a concrete share for the selected extracts and resolved recipients until the displayed deadline.','Create share','share-detail'],
revoke:['Revoke this share?','Future reads through this share are denied. External copies cannot be recalled.','Revoke','shares'],
'stop-sharing':['Stop future sharing?','Stop publishing new child shares. Existing concrete shares keep their current expiry and revocation state.','Stop future sharing','shares'],
'revoke-intent':['Revoke instruction and child shares?','Deny access through this instruction and its existing child shares. Independent access paths remain independently evaluated.','Revoke instruction','shares'],
approve:['Simulate verified independent approval?','Production requires current reviewer authority, verified step-up and exact scope. This control only demonstrates the resulting state.','Simulate approval','approvals'],
deny:['Deny this request?','Record the independent reviewer’s decision. No action starts.','Deny','approvals'],
raw:['Request bounded raw access?','Send the exact operation, limits and evidence scope for independent review. This does not grant access.','Request review','approvals'],
privacy:['Apply this privacy decision?','Use the current authorized selection revision; restriction and deletion progress are reported separately.','Submit decision','deletion'],
enroll:['Review enrollment handoff','Create registration, transmit a one-use secret by the operator’s secret channel and verify connector identity. No token is displayed here.','Review readiness','install'],
config:['Configuration handoff','Production shows a validated Kubernetes diff, source resourceVersion and field manager. These prototype fields are illustrative; no deployable manifest is generated.','Close',null],
discovery:['Request fresh process discovery?','This is new bounded evidence collection, subject to normal permissions, privacy and resource limits. It is not a passive preview.','Request discovery','capture-progress'],
survey:['Request a short protocol survey?','Explicitly acquire a bounded network sample, with the reviewed representation, privacy and source budget. No trial starts during preview.','Request survey','capture-progress'],
qualify:['Review qualification plan','Active tests need an operator-selected environment and explicit authorization. This prototype does not execute a test.','Open readiness','install'],
'revoke-cluster':['Revoke cluster registration?','Stop new dispatch and credential renewal. Disconnected work remains bounded by issued permits; retained evidence and deletion duties remain.','Revoke registration','clusters'],
cleanup:['Retry cleanup?','Request another attempt after correcting storage permissions. Keep the copy charged until deletion is verified.','Request attempt','deletion-detail'],
compare:['Run comparison?','Analyze only authorized compatible artifacts using qualified encrypted scratch; enforce both parent deadlines.','Request analysis','analysis-job']};
let pending=null,opener=null;
function notice(s){$('#notice').textContent=s;$('#notice').classList.add('visible');setTimeout(()=>$('#notice').classList.remove('visible'),4500);}
document.addEventListener('click',e=>{const a=e.target.closest('[data-download-kind]');if(a){demo.downloadKind=a.dataset.downloadKind;demo.downloadState='Ready';if(current()==='artifact-download')render(false);}const b=e.target.closest('[data-action]');if(!b)return;if(b.dataset.action==='download-file'){if(!['Ready','Interrupted'].includes(demo.downloadState)||demo.state!=='normal')return;if(['core','profile','files','command','companion'].includes(demo.downloadKind)&&!demo.downloadGrant)return;demo.downloadState='Completed (simulation)';render(false);notice('Download interaction simulated. No evidence file exists in this prototype.');}if(b.dataset.action==='download-cancel'){demo.downloadState='Cancelled';demo.state='normal';$('#state-picker').value='normal';render(false);notice('Transfer cancellation simulated; source evidence is unchanged.');}});
document.addEventListener('change',e=>{if(e.target.id==='download-kind'){demo.downloadKind=e.target.value;demo.downloadState='Ready';render(false);document.querySelector('#download-kind').focus();}});
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action;if(a.startsWith('live-')){liveAction(a,el);return;}if(a==='copy-case'){if(navigator.clipboard)navigator.clipboard.writeText('asservat://case/00000000-0000-4000-8000-000000000104').then(()=>notice('Case reference copied. It carries no access rights.')).catch(()=>notice('Case reference: asservat://case/00000000-0000-4000-8000-000000000104'));else notice('Case reference: asservat://case/00000000-0000-4000-8000-000000000104');return;}if(a==='capture'||['save','save-packet','save-syscall'].includes(a)){const save=a!=='capture';demo.operation=save?'recordingSave':'collect';demo.capture=save?'Succeeded':'Partial';if(save){demo.saveBefore=a==='save'?'20 seconds':'30 seconds';demo.savedSources=a==='save'?['Packet source','Syscall source']:[a==='save-packet'?'Packet source':'Syscall source'];}notice('Simulated submission; no request sent.');location.hash='#/capture-progress';return;}if(a==='signin'){location.hash='#/'+(demo.persona==='recipient'?'shared':demo.persona==='approver'?'approvals':'overview');return;}if(a==='add-rule'){demo.rules=4;render(false);notice('CPU condition added to the synthetic draft.');return;}if(!actions[a])return;pending=a;opener=el;const [title,desc,confirm]=actions[a];$('#dialog-title').textContent=title;$('#dialog-body').innerHTML=`<p>${desc}</p><p class="muted">Prototype action only. No request is sent.</p>`;$('#dialog-confirm').textContent=confirm;$('#action-dialog').showModal();});
$('#action-dialog').addEventListener('close',()=>{if($('#action-dialog').returnValue==='confirm'&&pending){const a=pending;if(a==='save'){demo.operation='recordingSave';demo.capture='Succeeded';}if(a==='capture'){demo.operation='collect';demo.capture='Partial';}if(['discovery','survey'].includes(a)){demo.operation=a;demo.capture='Queued';}if(a==='cancel')demo.capture='Cancelled';if(a==='approve')demo.review='Approved';if(a==='deny')demo.review='Denied';if(a==='suspend')demo.policy='Suspended';if(a==='publish-policy')demo.policy='Awaiting review';if(a==='share')demo.share='Active';if(a==='revoke')demo.share='Revoked';if(a==='stop-sharing')demo.intent='Publishing stopped';if(a==='revoke-intent')demo.intent='Revoked';if(a==='revoke-cluster')demo.cluster='Revoked';const dest=actions[a][3];notice('Simulated action recorded in this page only.');if(dest&&current()!==dest)location.hash='#/'+dest;else render(false);}else if(opener&&opener.isConnected)opener.focus();pending=null;});
document.addEventListener('change',e=>{if(e.target.dataset.profile){const p=e.target.dataset.profile;e.target.checked?demo.profiles.add(p):demo.profiles.delete(p);render(false);const target=[...document.querySelectorAll('[data-profile]')].find(x=>x.dataset.profile===p);if(target)target.focus();}if(e.target.name==='goal'){demo.goal=e.target.value;demo.profiles=new Set(demo.goal==='Network failures'?['Context','HTTP headers']:['Context']);render(false);document.querySelector('input[name=goal]:checked').focus();}});
document.addEventListener('input',e=>{if(e.target.hasAttribute('data-search')){const term=e.target.value.toLowerCase();document.querySelectorAll('[data-row]').forEach(r=>r.hidden=!r.textContent.toLowerCase().includes(term));}if(e.target.dataset.setting){const a=document.querySelector('[data-setting="segments"]'),b=document.querySelector('[data-setting="segmentSize"]'),n=Number(a.value)*Number(b.value);$('#ring-size').textContent=Number(a.value)>0&&Number(b.value)>0&&Number.isInteger(n)?`${n} MiB configured ring payload per source`:'Enter positive whole-number sizes; admission applies administrator limits.';}});
$('#persona').addEventListener('change',e=>{demo.persona=e.target.value;demo.state='normal';const dest=demo.persona==='recipient'?'shared':demo.persona==='approver'?'approvals':'overview';if(current()===dest)render();else location.hash='#/'+dest;});
$('#screen-picker').addEventListener('change',e=>location.hash='#/'+e.target.value);$('#state-picker').addEventListener('change',e=>{demo.state=e.target.value;render(false);});$('#prototype-toggle').addEventListener('click',()=>$('#prototype-dialog').showModal());['prototype-close','prototype-done'].forEach(id=>$('#'+id).addEventListener('click',()=>$('#prototype-dialog').close()));$('#prototype-dialog').addEventListener('close',()=>$('#prototype-toggle').focus());$('#reset-demo').addEventListener('click',()=>location.reload());$('#identity-button').addEventListener('click',()=>location.hash='#/access');$('#menu-toggle').addEventListener('click',()=>{const open=$('#sidebar').classList.toggle('open');$('#menu-toggle').setAttribute('aria-expanded',String(open));if(open)$('#navigation a').focus();});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#sidebar').classList.contains('open')){$('#sidebar').classList.remove('open');$('#menu-toggle').setAttribute('aria-expanded','false');$('#menu-toggle').focus();}});window.addEventListener('hashchange',()=>render());render(false);

document.addEventListener('change',e=>{if(e.target.hasAttribute('data-result-access')||e.target.hasAttribute('data-result-agent')){const agent=e.target.hasAttribute('data-result-agent');demo[agent?'resultAgent':'resultAccess']=e.target.checked;render(false);document.querySelector(agent?'[data-result-agent]':'[data-result-access]').focus();}});
